"""Agent (AG) catalogue for Part 7. Every agent must carry guardrails, fallback, KPIs, eval dimensions and cost."""

def C(model, I, S, O, calls, batch=False, hit=0.5, esc=0.0, line="B02", ttl="5m", note=""):
    return dict(model=model, I=I, S=S, O=O, calls=calls, batch=batch, hit=hit, esc=esc, line=line, ttl=ttl, note=note)

SEATS = "B09"
A = []
def ag(**k): A.append(k)

